+++ b/solution.py
@@ -1,3 +1,10 @@
+import re
+
 def slugify(text):
     """Return a URL slug: lowercase, runs of non-alphanumerics become one hyphen, no edge hyphens."""
-    raise NotImplementedError
+    # Convert to lowercase
+    text = text.lower()
+    # Replace any sequence of non-alphanumeric characters with a hyphen
