 def slugify(text):
-    """Return a URL slug: lowercase, runs of non-alphanumerics become one hyphen, no edge hyphens."""
-    raise NotImplementedError
+    """Return a URL slug: lowercase, runs of non-alphanumerics become one hyphen, no edge hyphens.
+
+    Parameters
+    ----------
+    text : str
+        The input string to slugify.
+
+    Returns
+    -------
+    str
+        The slugified version of ``text``.
+    """
+    if not isinstance(text, str):
+        raise TypeError("slugify expects a string")
+    # Convert to lowercase
+    lower = text.lower()
+    # Replace any sequence of non-alphanumeric characters with a single hyphen
+    slug = re.sub(r"[^a-z0-9]+", "-", lower)
+    # Strip leading/trailing hyphens
+    slug = slug.strip("-")
+    return slug
